WITH enriched AS (SELECT *, CUME_DIST() OVER (PARTITION BY event_type ORDER BY duration_sec DESC NULLS LAST) AS duration_sec_cume_dist, PERCENT_RANK() OVER (ORDER BY duration_sec) AS duration_sec_percent_rank FROM web_events) SELECT s.id, s.session_id, s.event_type, s.event_time, s.duration_sec, s.duration_sec_cume_dist, CASE WHEN event_type RLIKE '^(purchase|page_view)$' THEN 'CORE' ELSE 'GROUP_A' END AS event_type_zone, (SELECT MIN(t2.duration_sec) FROM web_events t2 WHERE t2.session_id = s.session_id) AS min_web_event_duration_sec FROM enriched s ORDER BY duration_sec
